        //   cos(S0, A) = cos(25.84°) ≈ 0.9
        //   cos(S1, A) = cos(36.87°) ≈ 0.8
        //   cos(S1, B) = cos(53.13°) ≈ 0.6
        val speaker0 = unit(-25.84)
        val speaker1 = unit(36.87)
        val alice = unit(0.0)
        val bob = unit(-16.26)

